-- Phase 9: authoritative Entity/Relation graph generation and ACL manifest.
ALTER TABLE t_entity ADD COLUMN source_id BIGINT NULL AFTER knowledge_base_id, ADD COLUMN permission_tags JSON NULL AFTER status, ADD KEY idx_entity_kb_status(knowledge_base_id,status);
ALTER TABLE t_relation ADD COLUMN source_id BIGINT NULL AFTER knowledge_base_id, ADD COLUMN permission_tags JSON NULL AFTER status, ADD KEY idx_relation_kb_status(knowledge_base_id,status);
CREATE TABLE IF NOT EXISTS t_claim_entity(id BIGINT PRIMARY KEY AUTO_INCREMENT,claim_code VARCHAR(64) NOT NULL,entity_code VARCHAR(64) NOT NULL,relation_role VARCHAR(32) DEFAULT 'ABOUT',created_time DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_claim_entity(claim_code,entity_code,relation_role));
CREATE TABLE IF NOT EXISTS t_card_entity(id BIGINT PRIMARY KEY AUTO_INCREMENT,knowledge_code VARCHAR(64) NOT NULL,entity_code VARCHAR(64) NOT NULL,relation_role VARCHAR(32) DEFAULT 'ABOUT',created_time DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_card_entity(knowledge_code,entity_code,relation_role));
CREATE TABLE IF NOT EXISTS t_index_graph_manifest(id BIGINT PRIMARY KEY AUTO_INCREMENT,release_id VARCHAR(64) NOT NULL,knowledge_base_id BIGINT NOT NULL,generation_id VARCHAR(128) NOT NULL,manifest_hash VARCHAR(64) NOT NULL,entity_count BIGINT NOT NULL DEFAULT 0,relation_count BIGINT NOT NULL DEFAULT 0,created_time DATETIME DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_graph_manifest_release(release_id),KEY idx_graph_manifest_kb_gen(knowledge_base_id,generation_id));
